function progress(value,tone){var n=Math.max(0,Math.min(100,Number(value)||0));return '<div class="se-progress '+(tone||'')+'"><span style="width:'+n+'%"></span></div>';}
function actionButton(label,fn,kind,icon){return '<button class="se-btn '+(kind||'')+'" onclick="'+fn+'">'+(icon?'<i class="ti '+icon+'"></i>':'')+h(label)+'</button>';}
