function empty(title,text){return '<div class="se-empty"><i class="ti ti-inbox"></i><strong>'+h(title)+'</strong><span>'+h(text)+'</span></div>';}
function field(label,id,type,options,value,wide){var input='';if(type==='select'){input='<select id="'+id+'">'+(options||[]).map(function(o){var v=Array.isArray(o)?o[0]:o,l=Array.isArray(o)?o[1]:o;return '<option value="'+h(v)+'" '+(String(v)===String(value)?'selected':'')+'>'+h(l)+'</option>';}).join('')+'</select>';}else if(type==='textarea'){input='<textarea id="'+id+'">'+h(value||'')+'</textarea>';}else{input='<input id="'+id+'" type="'+(type||'text')+'" value="'+h(value||'')+'"/>';}return '<div class="se-field '+(wide?'wide':'')+'"><label for="'+id+'">'+h(label)+'</label>'+input+'</div>';}
function table(headers,rows){if(!rows.length)return empty('No matching records','Change the filters or create the first record.');return '<div class="se-table-wrap"><table class="se-table"><thead><tr>'+headers.map(function(x){return '<th>'+h(x)+'</th>';}).join('')+'</tr></thead><tbody>'+rows.map(function(row){return '<tr>'+row.map(function(cell,i){return '<td data-label="'+h(headers[i])+'">'+cell+'</td>';}).join('')+'</tr>';}).join('')+'</tbody></table></div>';}

