var TABLES={programmes:'engagement_programmes',kpis:'engagement_kpi_definitions',assignments:'engagement_assignments',results:'engagement_person_results',credits:'engagement_activity_credits',recognitions:'engagement_recognitions',coaching:'engagement_coaching_plans',disputes:'engagement_disputes',notifications:'engagement_notifications',calendar:'engagement_calendar_events',drafts:'engagement_mobile_drafts',qr:'engagement_qr_sessions'};
async function queryTable(name){
  var cid=companyId();if(!cid)return [];
  var path='/'+TABLES[name]+'?select=*&company_id=eq.'+encodeURIComponent(cid)+'&limit=500';
  if(['notifications','calendar'].indexOf(name)>=0)path+='&order=created_at.desc';
  return await api(path);
}
async function loadData(force){
  if(SE.loading||(!force&&SE.loaded))return;SE.loading=true;
  var fallback=demos(),keys=Object.keys(TABLES);SE.schemaReady=true;SE.usingStarter=false;
  await Promise.all(keys.map(async function(k){try{var rows=await queryTable(k);SE.data[k]=rows&&rows.length?rows:fallback[k];if(k==='results'&&(!rows||!rows.length))SE.usingStarter=true;}catch(e){SE.schemaReady=false;SE.data[k]=fallback[k];}}));
  SE.data.config=fallback.config;
  try{var cid=companyId();var cfg=cid?await api('/engagement_configuration_versions?select=*&company_id=eq.'+encodeURIComponent(cid)+'&status=eq.published&order=version_no.desc&limit=1'):[];if(cfg&&cfg[0])SE.data.config=Object.assign({},fallback.config,cfg[0].configuration||{},cfg[0]);}catch(_){SE.schemaReady=false;}
  try{var local=JSON.parse(localStorage.getItem('auris360_se_drafts')||'[]');if(local.length)SE.data.drafts=local.concat((SE.data.drafts||[]).filter(function(x){return !x.local_only;}));}catch(_){}
  SE.loaded=true;SE.loading=false;render();
}

