function renderTeam(){var rs=SE.data.results||[];return '<div class="se-grid cards-5">'+metric('ti-gauge','Team score',Math.round(rs.reduce(function(a,x){return a+(+x.score||0);},0)/(rs.length||1))+'%','Authorised team only','blue')+metric('ti-circle-check','On track',rs.filter(function(x){return x.status==='on_track';}).length,'')+metric('ti-alert-circle','At risk',rs.filter(function(x){return x.status==='at_risk';}).length,'','amber')+metric('ti-circle-x','Off track',rs.filter(function(x){return x.status==='off_track';}).length,'Human review required','red')+metric('ti-hourglass','Pending validation',rs.reduce(function(a,x){return a+(+x.pending||0);},0),'Excluded from failure','blue')+'</div><div class="se-toolbar" style="margin-top:14px"><div><div class="se-card-title">Team performance</div><div class="se-card-sub">No public worst-performer ranking; results are ordered by name.</div></div>'+actionButton('Start team review',"seOpenDrawer('team-review')",'primary','ti-checklist')+'</div>'+table(['Employee','Programme','Hazards','Toolbox','Training','Score','Review','Status'],rs.slice().sort(function(a,b){return a.person_name.localeCompare(b.person_name);}).map(function(x){return [h(x.person_name),h(x.programme_name),h(x.hazards),h(x.toolbox)+'%',h(x.training)+'%','<b>'+h(x.score)+'%</b>',h(statusLabel(x.review_state)),badge(x.status)+' <button class="se-btn icon" onclick="seOpenDrawer(\'person\',\''+h(x.id)+'\')"><i class="ti ti-chevron-right"></i></button>'];}));}

function renderProgrammes(){var ps=SE.data.programmes||[];return '<div class="se-toolbar"><div><div class="se-card-title">KPI programme library</div><div class="se-card-sub">Published versions are immutable; Draft → Review → Published → Retired.</div></div>'+(canManage()?actionButton('New programme',"seOpenDrawer('programme')",'primary','ti-plus'):'')+'</div>'+table(['Code','Programme','Population','KPIs','Weight','Period','Version','Owner','Status',''],ps.map(function(x){return [h(x.code),'<b>'+h(x.name)+'</b>',h(x.population),h(x.kpi_count||0),h(x.weight_total||100)+'%',h(x.period),h('v'+(x.version_no||1)),h(x.owner||'-'),badge(x.status),'<button class="se-btn icon" onclick="seOpenDrawer(\'programme-detail\',\''+h(x.id)+'\')"><i class="ti ti-chevron-right"></i></button>'];}));}

function renderAssignments(){var xs=SE.data.assignments||[];return '<div class="se-grid cards-5">'+metric('ti-users','Active assignments',xs.filter(function(x){return x.status==='active';}).reduce(function(a,x){return a+(+x.people_count||0);},0),'Employees and workers')+metric('ti-user-plus','Starting soon',23,'Effective-dated')+metric('ti-clock-off','Expiring',11,'Next 30 days','amber')+metric('ti-user-question','Unassigned',7,'Admin exception','red')+metric('ti-arrows-split','Conflicts',2,'Resolve before finalisation','amber')+'</div><div class="se-toolbar" style="margin-top:14px"><div><div class="se-card-title">Programme assignments</div><div class="se-card-sub">Population preview and conflict resolution protect locked history.</div></div>'+(canManage()?actionButton('New assignment',"seOpenDrawer('assignment')",'primary','ti-plus'):'')+'</div>'+table(['Target population','Programme','Scope','People','Effective','Override','Status',''],xs.map(function(x){return ['<b>'+h(x.target_name)+'</b>',h(x.programme_name),h(x.scope),h(x.people_count||0),fmtDate(x.effective_from),h(x.override_reason||'None'),badge(x.status),'<button class="se-btn icon" onclick="seOpenDrawer(\'assignment-detail\',\''+h(x.id)+'\')"><i class="ti ti-chevron-right"></i></button>'];}));}

function renderMonthly(){var rs=SE.data.results||[];return '<div class="se-grid cards-5">'+metric('ti-users','Employees due',rs.length,'Current authorised scope')+metric('ti-checkbox','Complete',rs.filter(function(x){return x.review_state==='ready';}).length,'Ready for approval')+metric('ti-message-question','Incomplete',rs.filter(function(x){return x.review_state!=='ready';}).length,'Context or evidence required','amber')+metric('ti-shield-search','Pending validation',rs.reduce(function(a,x){return a+(+x.pending||0);},0),'Cannot reduce score','blue')+metric('ti-lock','Locked',18,'Approved immutable snapshots')+'</div><div class="se-toolbar" style="margin-top:14px"><div><div class="se-card-title">August 2026 monthly review</div><div class="se-card-sub">Zero, No Data, Pending, Not Due and N/A remain distinct.</div></div>'+actionButton('Submit completed',"seSubmitMonth()",'primary','ti-send')+'</div>'+table(['Employee','Programme','Score','Pending','Exclusions','Review state','Status',''],rs.map(function(x){return ['<b>'+h(x.person_name)+'</b>',h(x.programme_name),'<b>'+h(x.score)+'%</b>',x.pending?badge('pending',x.pending+' pending'):badge('accepted','None'),h(x.excluded||0),h(statusLabel(x.review_state)),badge(x.status)+' <button class="se-btn icon" onclick="seOpenDrawer(\'month\',\''+h(x.id)+'\')"><i class="ti ti-chevron-right"></i></button>'];}));}

function renderValidation(){var xs=SE.data.credits||[];return '<div class="se-grid cards-5">'+metric('ti-shield-search','Awaiting review',xs.length,'Authorised scope','blue')+metric('ti-alert-triangle','Hazards',xs.filter(function(x){return x.activity_type.indexOf('Hazard')>=0;}).length,'')+metric('ti-qrcode','Attendance',xs.filter(function(x){return x.activity_type.indexOf('Toolbox')>=0;}).length,'')+metric('ti-paperclip','Evidence issues',xs.filter(function(x){return x.quality!=='Complete'&&x.quality!=='Verified source';}).length,'','amber')+metric('ti-clock','SLA at risk',1,'Escalates to queue owner','red')+'</div><div class="se-toolbar" style="margin-top:14px"><div><div class="se-card-title">Activity validation queue</div><div class="se-card-sub">Quality and eligibility are checked before any personal credit is counted.</div></div>'+actionButton('Mobile validation',"seOpenMobile('validation')",'blue','ti-device-mobile')+'</div>'+table(['Activity','Employee','Source','Submitted','Quality','Potential KPI','SLA','Status','Decision'],xs.map(function(x){return ['<b>'+h(x.activity_type)+'</b>',h(x.person_name),h(x.source_ref),fmtDate(x.submitted_at),h(x.quality),h(x.potential_kpi),h(x.sla||'-'),badge(x.status),'<button class="se-btn" onclick="seOpenDrawer(\'validation\',\''+h(x.id)+'\')">Review</button>'];}));}

